import { initUI } from './UI';
import { getImgFromURL, getFalseColor } from '../../../../lib';

export class FluidSystem {
	public divText: HTMLElement;
	public mouse: number[];
	public pts: number[][];

	public fluid: Fluid;

	public t = 0.0;

	public vecs: number[][] = [];

	public emmiters: number[][] = [];
	public xx = 1;
	public yy = 1;

	public img: HTMLImageElement;
	public activated = false;
	public showVec = false;
	public url: string = '';

	constructor(div, divUI) {
		this.init();
		this.initUI(divUI);

		let url;
		url = 'https://raw.githubusercontent.com/NamjuLee/data/master/img/Boston_02.jpg';
		this.importImg(url);
	}
	public importImg(url: string) {
		this.url = url;

		getImgFromURL(url).then((img: HTMLImageElement | void) => {
			if (!img) return;
			this.img = img;
			img.onload = () => {
				const canvas = document.createElement('canvas');
				const ctx = canvas.getContext('2d') as CanvasRenderingContext2D;

				if (ctx) {
					ctx.drawImage(this.img, 0, 0, this.fluid.N, this.fluid.N);

					const data: ImageData | undefined = ctx.getImageData(0, 0, this.fluid.N, this.fluid.N);
					if (data) {
						for (let y = 0; y < this.fluid.N; ++y) {
							for (let x = 0; x < this.fluid.N; ++x) {
								const d = data.data[(x + this.fluid.N * y) * 4];
								if (d < 200) {
									this.fluid.cellFixed.push([x, y]);
								}
							}
						}
					}
				}
			};

			this.init();
		});
	}
	public initUI(divUI) {
		initUI(divUI, this);

		this.emmiters.push([Math.floor(0.5 * this.fluid.N), Math.floor(0.5 * this.fluid.N)]);
	}
	public init() {
		this.fluid = new Fluid(0.02, 0, 0.0000001);
		this.emmiters = [];
		this.emmiters.push([Math.floor(0.5 * this.fluid.N), Math.floor(0.5 * this.fluid.N)]);
		this.activated = true;
	}
	public render(ctx: CanvasRenderingContext2D): void {
		this.activated && this.RenderIndependentCanvas(ctx);
	}
	public RenderIndependentCanvas(ctx: CanvasRenderingContext2D) {
		for (let k = 0; k < this.emmiters.length; ++k) {
			let cx = this.emmiters[k][0];
			let cy = this.emmiters[k][1];
			for (let i = -1; i <= 1; i++) {
				for (let j = -1; j <= 1; j++) {
					// this.fluid.addDensity(cx + i, cy + j, random(50, 150));
					// console.log((Math.random() * 100) + 50)
					this.fluid.addDensity(cx + i, cy + j, Math.random() * 5);
				}
			}
		}

		for (let k = 0; k < this.emmiters.length; ++k) {
			let cx = this.emmiters[k][0];
			let cy = this.emmiters[k][1];
			for (let i = 0; i < 2; i++) {
				// let angle = noise(t) * Math.PI * 2;
				// let v = p5.Vector.fromAngle(angle);
				// v.mult(0.2);
				// this.t += 0.01;
				// this.fluid.addVelocity(cx, cy, v.x, v.y);
				this.fluid.addVelocity(cx, cy, this.xx, this.yy);
				// this.fluid.addVelocity(cx, cy, 1 , 1);
			}
		}

		this.fluid.step();
		this.fluid.renderD(ctx);
		this.showVec && this.fluid.renderV(ctx);
	}
	public mouseClick(x: number, y: number): void {
		const xx = Math.floor(x / this.fluid.SCALE);
		const yy = Math.floor(y / this.fluid.SCALE);
		this.emmiters.push([xx, yy]);
	}
	public mouseDrag(x: number, y: number) {
		const xx = Math.floor(x / this.fluid.SCALE);
		const yy = Math.floor(y / this.fluid.SCALE);
		this.fluid.cellFixed.push([xx, yy]);
	}
	public rotation(angle: number) {
		const theta = (angle * Math.PI) / 180;
		this.xx = Math.cos(theta);
		this.yy = Math.sin(theta);
	}
	public mouseMove(x: number, y: number) {
		const xx = Math.floor(x / this.fluid.SCALE);
		const yy = Math.floor(y / this.fluid.SCALE);
		const d = this.fluid.density[xx + yy * this.fluid.N];
		if (d) {
			this.divText.innerHTML = `${d}`;
		}
	}
	public toJson() {
		// this.fluid.toJson();

		const data = [];

		for (let i = 0; i < this.fluid.N; i++) {
			for (let j = 0; j < this.fluid.N; j++) {
				let density = this.fluid.density[IX(i, j, this.fluid.N)];
				let x = i * this.fluid.SCALE;
				let y = j * this.fluid.SCALE;
				data.push({
					x,
					y,
					density,
				});
			}
		}

		// console.log(data)
		downloadJson(JSON.stringify(data));
	}
	public toPng() {
		// console.log('png');
	}
	public toObj() {
		// console.log('obj');
	}
}

const downloadJson = (collection, name = 'download') => {
	const link = document.createElement('a');
	link.href = 'data:application/json;charset=utf-8,' + encodeURIComponent(collection);
	link.download = `${name}`;
	link.click();
};

// Fluid cube class
export class Fluid {
	public N = 64;
	public iter = 2; // 16;
	public SCALE = 8;
	public t = 0;

	public visScale = 0.01;

	// size: number;
	public dt: number;
	public diff: number;
	public visc: number;

	public s: Float32Array;
	public density: Float32Array;
	public Vx: Float32Array;
	public Vy: Float32Array;
	public Vx0: Float32Array;
	public Vy0: Float32Array;

	public cellFixed: number[][] = [];

	constructor(dt: number, diffusion: number, viscosity: number) {
		// this.size = this.SCALE;
		this.dt = dt;
		this.diff = diffusion;
		this.visc = viscosity;

		this.s = new Float32Array(this.N * this.N).fill(0);
		this.density = new Float32Array(this.N * this.N).fill(0.01);

		this.Vx = new Float32Array(this.N * this.N).fill(0);
		this.Vx0 = new Float32Array(this.N * this.N).fill(0);

		this.Vy = new Float32Array(this.N * this.N).fill(0);
		this.Vy0 = new Float32Array(this.N * this.N).fill(0);
	}
	// step method
	public step() {
		const { N, iter, dt, visc, diff, cellFixed } = this;

		// 속도 확산
		diffuse(1, this.Vx0, this.Vx, visc, dt, N, iter, cellFixed);
		diffuse(2, this.Vy0, this.Vy, visc, dt, N, iter, cellFixed);

		// 발산 제거 (투영)
		project(this.Vx0, this.Vy0, this.Vx, this.Vy, N, iter, cellFixed);

		// 속도 이동 (advection)
		advect(1, this.Vx, this.Vx0, this.Vx0, this.Vy0, dt, N, cellFixed);
		advect(2, this.Vy, this.Vy0, this.Vx0, this.Vy0, dt, N, cellFixed);

		// 다시 투영 → 속도 필드 불가역 발산 없앰
		project(this.Vx, this.Vy, this.Vx0, this.Vy0, N, iter, cellFixed);

		// 밀도 확산 → 이동
		diffuse(0, this.s, this.density, diff, dt, N, iter, cellFixed);
		advect(0, this.density, this.s, this.Vx, this.Vy, dt, N, cellFixed);
	}

	// method to add density
	public addDensity(x: number, y: number, amount: number) {
		let index = IX(x, y, this.N);
		this.density[index] += amount;
	}
	// method to add velocity
	public addVelocity(x: number, y: number, amountX: number, amountY: number) {
		let index = IX(x, y, this.N);
		this.Vx[index] += amountX;
		this.Vy[index] += amountY;
	}
	// function to render density
	public renderD(ctx: CanvasRenderingContext2D) {
		for (let i = 0; i < this.N; i++) {
			for (let j = 0; j < this.N; j++) {
				let x = i * this.SCALE;
				let y = j * this.SCALE;
				let d = this.density[IX(i, j, this.N)];

				// let col = `rgb(${(d + 50) % 255}, 200,${d})`;
				// console.log('ddd', `${(d + 50) % 255}, 200,${d}`);
				// console.log(this.density);
				// fill(d);
				// noStroke();
				// rect(x, y, this.SCALE, this.SCALE);
				// console.log(d);
				if (d === 0) {
					ctx.fillStyle = `rgb(255, 255, 255)`;
				} else {
					const col = getFalseColor(d * this.visScale);
					ctx.fillStyle = `rgb(${col[0]}, ${col[1]},${col[2]})`;
				}
				ctx.beginPath();
				ctx.rect(x, y, this.SCALE, this.SCALE);
				ctx.fill();
				ctx.lineWidth = 0.2;
				ctx.strokeStyle = '#ff0000';
				// ctx.stroke()
			}
		}
	}

	// function to render velocity
	public renderV(ctx: CanvasRenderingContext2D) {
		for (let i = 0; i < this.N; i++) {
			for (let j = 0; j < this.N; j++) {
				let x = i * this.SCALE;
				let y = j * this.SCALE;
				// let vx = this.Vx[IX(i, j, k)];
				// let vy = this.Vy[IX(i, j, k)];
				let vx = this.Vx[IX(i, j, this.N)];
				let vy = this.Vy[IX(i, j, this.N)];
				// this.canvas.stroke(0);

				if (!(Math.abs(vx) < 0.1 && Math.abs(vy) <= 0.1)) {
					ctx.lineWidth = 2;
					ctx.beginPath();
					ctx.moveTo(x, y);
					ctx.lineTo(x + vx * this.SCALE, y + vy * this.SCALE);
					ctx.stroke();
					//   line(x, y, x + vx * this.SCALE, y + vy * this.SCALE);
				}
			}
		}
	}
}

