import { FluidSystem } from '..';

export const initUI = (divContainer, fluidSimulation: FluidSystem) => {
	let divHost = document.createElement('div');
	divHost.style.position = 'absolute';
	// divHost.style.left = '450px';
	// divHost.style.height = '50px';
	divContainer.appendChild(divHost);

	let divBtn = document.createElement('button');
	divBtn.textContent = 'Reset';
	divBtn.style.width = '60px';
	divBtn.style.height = '20px';
	divBtn.onclick = () => {
		fluidSimulation.init();
	};
	divHost.appendChild(divBtn);

	let divInput = document.createElement('div');
	let inputURL = document.createElement('input');
	inputURL.value = 'https://raw.githubusercontent.com/NamjuLee/data/master/img/building%20footprint.jpg';
	inputURL.addEventListener('keydown', (e: KeyboardEvent) => {
		if (e.code === 'Enter') {
			fluidSimulation.importImg(inputURL.value);
		}
	});
	divInput.appendChild(inputURL);
	divHost.appendChild(divInput);

	let div5 = document.createElement('div');
	div5.innerHTML = 'time';
	div5.style.height = '50px';
	div5.style.width = '100px';
	divHost.appendChild(div5);

	let sliderD = document.createElement('input');
	sliderD.type = 'range';
	sliderD.min = '0.0001';
	sliderD.max = '0.7';
	sliderD.step = '0.0001';
	sliderD.oninput = () => {
		const val = +sliderD.value as number;
		fluidSimulation.fluid.dt = val;
		// console.log('fd.fluid.visScale', fluidSimulation.fluid.visScale);
	};
	div5.appendChild(sliderD);

	let div = document.createElement('div');
	div.innerHTML = 'Vis Scale';
	div.style.height = '50px';
	div.style.width = '100px';
	divHost.appendChild(div);

	let sliderA = document.createElement('input');
	sliderA.type = 'range';
	sliderA.min = '0.000001';
	sliderA.max = '0.8';
	sliderA.step = '0.00001';
	sliderA.oninput = () => {
		const val = +sliderA.value as number;
		fluidSimulation.fluid.visScale = val;
		// console.log('fd.fluid.visScale', fluidSimulation.fluid.visScale);
	};
	div.appendChild(sliderA);

	const div2 = document.createElement('div');
	div2.innerHTML = 'Viscosity';
	// div2.style.backgroundColor = '#ff0000';
	div2.style.height = '50px';
	div2.style.width = '100px';

	divHost.appendChild(div2);

	const sliderB = document.createElement('input');
	sliderB.type = 'range';
	sliderB.min = '0.000000';
	sliderB.max = '0.0001';
	sliderB.step = '0.0000001';
	sliderB.oninput = () => {
		const val = +sliderB.value as number;
		fluidSimulation.fluid.visc = val;
		// console.log('fd.fluid.visScale', fluidSimulation.fluid.visScale);
	};
	div2.appendChild(sliderB);

	const div3 = document.createElement('div');
	div3.innerHTML = 'rotation';
	// div3.style.backgroundColor = '#ff0000';
	div3.style.height = '50px';
	div3.style.width = '100px';

	divHost.appendChild(div3);

	const sliderC = document.createElement('input');
	sliderC.type = 'range';
	sliderC.min = '0.000000';
	sliderC.max = '360';
	sliderC.step = '0.0000001';
	sliderC.oninput = () => {
		const val = +sliderC.value as number;
		fluidSimulation.rotation(val);
		// console.log('val', val);
	};
	div3.appendChild(sliderC);

	const divText = document.createElement('div');
	divText.innerHTML = 'rotation';
	// divText.style.backgroundColor = '#ff0000';
	divText.style.height = '50px';
	divText.style.width = '100px';
	fluidSimulation.divText = divText;
	divHost.appendChild(divText);

	const divVecViz = document.createElement('div');
	divVecViz.innerHTML = 'Show Vec';
	// divVecViz.style.backgroundColor = '#ff0000';
	divVecViz.style.height = '50px';
	divVecViz.style.width = '100px';
	// fluidSimulation.divVecViz = divVecViz;
	divHost.appendChild(divVecViz);

	const inputFile = document.createElement('input');
	inputFile.type = 'checkbox';
	inputFile.onchange = () => {
		fluidSimulation.showVec = !fluidSimulation.showVec;
	};
	divVecViz.appendChild(inputFile);

	const divToJson = document.createElement('button');
	divToJson.innerHTML = 'Json';
	// divToJson.style.backgroundColor = '#ff0000';
	divToJson.style.height = '20px';
	divToJson.style.width = '50px';
	divToJson.onclick = () => {
		fluidSimulation.toJson();
	};
	divHost.appendChild(divToJson);

	const divToObj = document.createElement('button');
	divToObj.innerHTML = 'obj';
	// divToObj.style.backgroundColor = '#ff0000';
	divToObj.style.height = '20px';
	divToObj.style.width = '50px';
	divToObj.onclick = () => {
		fluidSimulation.toObj();
	};
	divHost.appendChild(divToObj);

	const divToPng = document.createElement('button');
	divToPng.innerHTML = 'png';
	// divToPng.style.backgroundColor = '#ff0000';
	divToPng.style.height = '20px';
	divToPng.style.width = '50px';
	divToPng.onclick = () => {
		fluidSimulation.toPng();
	};
	divHost.appendChild(divToPng);

	const divRefer = document.createElement('div');
	divRefer.innerHTML = 'Ref:<br>Fluid Simulation <br>By Daniel Shiffman';
	// divRefer.style.backgroundColor = '#ff0000';
	divRefer.style.height = '50px';
	divRefer.style.width = '300px';
	divRefer.style.fontSize = '14px';
	divHost.appendChild(divRefer);
};
